28	public class DataSourcesMagicCommand implements MagicCommandFunctionality {
29	
30	  public static final String DATASOURCES = "%datasources";
31	
32	  private KernelFunctionality kernel;
33	
34	  public DataSourcesMagicCommand(KernelFunctionality kernel) {
35	    this.kernel = kernel;
36	  }
37	
38	  @Override
39	  public MagicCommandOutcomeItem execute(MagicCommandExecutionParam param) {
40	    return dataSource(DATASOURCES, param.getCommand());
41	  }
42	
43	  @Override
44	  public boolean matchCommand(String command) {
45	    String[] commandParts = MagicCommandUtils.splitPath(command);
46	    return commandParts.length > 0 && commandParts[0].equals(DATASOURCES);
47	  }
48	
49	  @Override
50	  public String getMagicCommandName() {
51	    return DATASOURCES;
52	  }
53	
54	  protected MagicCommandOutcomeItem dataSource(String source, String command) {
55	    String[] parts = command.split(" ");
56	    if (parts.length != 2) {
57	      return new MagicCommandOutput(MagicCommandOutcomeItem.Status.ERROR, WRONG_FORMAT_MSG);
58	    } else if (!parts[1].contains("jdbc:")) {
59	      return new MagicCommandOutput(MagicCommandOutcomeItem.Status.ERROR, "Incorrect jdbc url.");
60	    }
61	
62	    HashMap<String, Object> params = new HashMap<>();
63	    params.put(source, parts[1]);
64	    kernel.updateEvaluatorParameters(new EvaluatorParameters(params));
65	    return new MagicCommandOutput(MagicCommandOutcomeItem.Status.OK);
66	
67	  }
68	}
