79	  public static void main(final String[] args) {
80	    KernelRunner.run(() -> {
81	      String id = uuid();
82	      CommRepository commRepository = new BeakerXCommRepository();
83	      KernelConfigurationFile configurationFile = new KernelConfigurationFile(args);
84	      KernelSocketsFactoryImpl kernelSocketsFactory = new KernelSocketsFactoryImpl(
85	              configurationFile);
86	      EvaluatorParameters params = getKernelParameters(BeakerXSystemImpl.getINSTANCE());
87	      NamespaceClient beakerxClient = NamespaceClient.create(id, configurationFile, commRepository);
88	      MagicCommandConfiguration magicConfiguration = new MagicCommandConfigurationImpl();
89	      SQLEvaluator evaluator = new SQLEvaluator(id, id, params, beakerxClient, magicConfiguration.patterns(),new ClasspathScannerImpl());
90	      return new SQL(id,
91	              evaluator,
92	              new Configuration(
93	                      kernelSocketsFactory,
94	                      new SQLCustomMagicCommandsImpl(),
95	                      commRepository,
96	                      new SQLBeakerXServer(new GetUrlArgHandler(beakerxClient)),
97	                      magicConfiguration,
98	                      new BeakerXJsonConfig()));
99	    });
100	  }
