103	  static EvaluatorParameters getKernelParameters(BeakerXSystem beakerXSystem) {
104	    Map<String, Object> kernelParameters = new HashMap<>();
105	    kernelParameters.put(IMPORTS, new DefaultJVMVariables().getImports());
106	    kernelParameters = getDefaultConnectionString(beakerXSystem, kernelParameters);
107	    return new EvaluatorParameters(kernelParameters);
108	  }
109	
110	  private static Map<String, Object> getDefaultConnectionString(BeakerXSystem beakerXSystem, Map<String, Object> kernelParameters) {
111	    String uri = beakerXSystem.getenv(BEAKERX_SQL_DEFAULT_JDBC);
112	    if (uri != null && uri.contains("jdbc:")) {
113	      logger.info("Setting default connection string to " + uri);
114	      kernelParameters.put(DEFAULT_DATASOURCE, uri);
115	    } else if (uri != null) {
116	      logger.warning("Ignoring incorrectly formatted " + BEAKERX_SQL_DEFAULT_JDBC + ": " + uri);
117	    }
118	    return kernelParameters;
119	  }
